package com.citacloud.springboot.contacloud.app.repositories;
import com.citacloud.springboot.contacloud.app.models.*;import jakarta.persistence.LockModeType;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.LocalDate;import java.util.*;
public interface ConteoFisicoRepository extends JpaRepository<ConteoFisico,UUID>{
 @EntityGraph(attributePaths={"almacen","almacen.sucursal"})@Query("select c from ConteoFisico c where c.tenantId=:t and c.empresaId=:e and (:q='' or lower(c.numero) like concat('%',:q,'%') or lower(coalesce(c.referencia,'')) like concat('%',:q,'%') or exists(select l.id from LineaConteoFisico l where l.conteoId=c.id and (lower(l.producto) like concat('%',:q,'%') or lower(l.codigo) like concat('%',:q,'%')))) and (:desde is null or c.fecha>=:desde) and (:hasta is null or c.fecha<=:hasta) and (:estado is null or c.status=:estado) and (:almacen is null or c.almacenId=:almacen) and (:tipo is null or c.tipo=:tipo)")Page<ConteoFisico> buscar(@Param("t")UUID t,@Param("e")UUID e,@Param("q")String q,@Param("desde")LocalDate desde,@Param("hasta")LocalDate hasta,@Param("estado")EstadoConteoFisico estado,@Param("almacen")UUID almacen,@Param("tipo")TipoConteoFisico tipo,Pageable pageable);
 @EntityGraph(attributePaths={"almacen","almacen.sucursal"})Optional<ConteoFisico> findByIdAndTenantIdAndEmpresaId(UUID id,UUID t,UUID e);
 @Lock(LockModeType.PESSIMISTIC_WRITE)@EntityGraph(attributePaths={"almacen","almacen.sucursal"})@Query("select c from ConteoFisico c where c.id=:id and c.tenantId=:t and c.empresaId=:e")Optional<ConteoFisico> bloquear(@Param("id")UUID id,@Param("t")UUID t,@Param("e")UUID e);
}
